import json
import re
from collections import Counter

REPLACE_NONE = "None"

def task_func(json_str):
    data = json.loads(json_str)

    def clean(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is None:
                    continue
                new_dict[k] = clean(v)
            return new_dict
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                if item is None:
                    continue
                new_list.append(clean(item))
            return new_list
        elif isinstance(obj, str):
            return re.sub(r'[\w\.-]+@[\w\.-]+\.\w+', REPLACE_NONE, obj)
        else:
            return obj

    cleaned = clean(data)

    def flatten(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from flatten(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from flatten(item)
        else:
            yield obj

    value_counts = Counter(flatten(cleaned))

    return {"data": cleaned, "value_counts": value_counts}

